        if (enemy.hp < enemy.maxHp * 0.5) {
          enemy.hp = Math.min(enemy.maxHp, enemy.hp + (ability.values.healAmount ?? 0))
          enemy.abilityCooldowns[ability.id] = ability.cooldownMs
        }
      } else if (ability.effect === 'damageBuff') {
        enemy.baseDamage *= ability.values.damageMultiplier ?? 1.2
        enemy.abilityCooldowns[ability.id] = ability.cooldownMs
      } else if (ability.effect === 'instantAttack') {
        this.performEnemyAttack(enemy)
        enemy.abilityCooldowns[ability.id] = ability.cooldownMs
      }
    }
  }

  private checkCombatResolution() {
    const allDead = this.state.enemies.every((e) => !e.alive)
    if (allDead) {
      this.onVictory()
    } else if (this.state.player.hp <= 0) {
      this.state.phase = 'defeat'
    }
  }

  private onVictory() {
    this.state.phase = 'victory'
    this.state.fightCount += 1
    const needsLevel =
      this.state.level < MAX_LEVEL &&
      this.state.fightCount >= this.state.fightsToNextLevel
    if (needsLevel) {
      this.state.level += 1
      this.state.talentPoints += 1
      const nextTarget = LEVEL_TARGETS[Math.min(this.state.level - 1, LEVEL_TARGETS.length - 1)]
      this.state.fightsToNextLevel = this.state.fightCount + nextTarget
      this.state.phase = 'levelUp'
    }
  }

  public resumeAfterLevel() {
    if (this.state.phase === 'levelUp' || this.state.phase === 'victory') {
      this.spawnNextEnemy(false)
      this.state.phase = 'combat'
      this.emit()
    }
  }

  public selectNextTarget() {
    const alive = this.state.enemies.filter((e) => e.alive)
    if (!alive.length) return
    const current = this.getCurrentTarget()
    const currentIdx = alive.findIndex((e) => e.id === current?.id)
    const next = (currentIdx + 1) % alive.length
    const target = alive[next]
    const fullIdx = this.state.enemies.findIndex((e) => e.id === target.id)
    this.state.targetIndex = fullIdx >= 0 ? fullIdx : 0
    this.emit()
  }

  public selectPrevTarget() {
    const alive = this.state.enemies.filter((e) => e.alive)
    if (!alive.length) return
    const current = this.getCurrentTarget()
    const currentIdx = alive.findIndex((e) => e.id === current?.id)
    const next = (currentIdx - 1 + alive.length) % alive.length
    const target = alive[next]
    const fullIdx = this.state.enemies.findIndex((e) => e.id === target.id)
    this.state.targetIndex = fullIdx >= 0 ? fullIdx : 0
    this.emit()
  }

  public activateBlock() {
    const player = this.state.player
    if (player.blockCooldownMs > 0) return
    player.buffs.push({
      id: 'block',
      remainingMs: BLOCK_DURATION_MS,
      type: 'damageReduction',
      damageReduction: BLOCK_DAMAGE_REDUCTION,
    })
    player.attackTimerMs += BLOCK_DURATION_MS
    player.blockCooldownMs = BLOCK_COOLDOWN_MS
    this.recalculateDerivedStats()
    this.emit()
  }

  public activateAbility(slot: AbilitySlot) {
    const abilityId = this.state.equippedAbilityIds[slot]
    if (!abilityId) return
    const ability = abilitiesById.get(abilityId)
    if (!ability) return
    const remaining = this.state.player.abilityCooldowns[slot]
    if (remaining > 0) return

    switch (ability.effect) {
      case 'generator':
        this.castGenerator(ability)
        break
      case 'attackSpeedBuff':
        this.castAttackSpeedBuff(ability)
        break
      case 'empowerNextAttack':
        this.castEmpower(ability)
        break
      case 'consumeRage':
        this.castConsumer(ability)
        break
    }
    this.state.player.abilityCooldowns[slot] = ability.cooldownMs
    this.emit()
  }

  private castGenerator(ability: AbilityDefinition) {
    this.performPlayerAttack()
    this.state.player.attackTimerMs = this.getPlayerAttackInterval()
    this.state.player.rage = Math.min(
      this.state.player.rageCap,
      this.state.player.rage + (ability.values.rageGain ?? 1),
    )
  }

  private castAttackSpeedBuff(ability: AbilityDefinition) {
    const bonus = ability.values.attackSpeedBonus ?? 0.3
    const duration = ability.values.durationMs ?? 4000
    this.state.player.buffs.push({
      id: ability.id,
      remainingMs: duration,
      type: 'attackSpeed',
      attackSpeedBonus: bonus,
    })
    this.recalculateDerivedStats()
  }

  private castEmpower(ability: AbilityDefinition) {
    this.state.player.empoweredAttack = {
      slowPercent: ability.values.slowPercent ?? 0.25,
      slowDurationMs: ability.values.slowDurationMs ?? 3000,
    }
  }

  private castConsumer(ability: AbilityDefinition) {
    const target = this.getCurrentTarget()
    if (!target) return
    const rage = this.state.player.rage
    const base = ability.values.consumeBaseDamage ?? 5
    const per = ability.values.consumePerRage ?? 8
    const damage = base + per * rage
    this.state.player.rage = 0
    this.performInterrupt()
    this.dealDamageToEnemy(target, damage)
  }

  private performInterrupt() {
    this.state.player.attackTimerMs = this.getPlayerAttackInterval()
  }

  private dealDamageToEnemy(enemy: EnemyState, damage: number) {
    if (!enemy.alive) return
    enemy.hp = Math.max(0, enemy.hp - damage)
    if (enemy.hp <= 0) {
      enemy.alive = false
    }
  }

  private getCurrentTarget() {
    const alive = this.state.enemies.filter((e) => e.alive)
    if (!alive.length) return null
    const desired = this.state.enemies[this.state.targetIndex]
    if (desired?.alive) return desired
    return alive[0]
  }

  private spawnNextEnemy(isTutorial: boolean) {
    const definition = isTutorial
      ? enemiesById.get('tutorialDummy')
      : this.randomEnemy()
    if (!definition) return
    const enemy = this.instantiateEnemy(definition)
    this.state.enemies = [enemy]
    this.state.targetIndex = 0
    this.state.phase = 'combat'
  }

  private randomEnemy(): EnemyDefinition | undefined {
    const pool = enemyList.filter((e) => e.id !== 'tutorialDummy')
    return pool[Math.floor(Math.random() * pool.length)]
  }

  private instantiateEnemy(def: EnemyDefinition) {
    const cooldowns: Record<string, number> = {}
    def.abilities.forEach((a) => (cooldowns[a.id] = 0))
    return {
      id: def.id,
      name: def.name,
      hp: def.maxHp,
      maxHp: def.maxHp,
      baseDamage: def.baseDamage,
      attackTimerMs: this.rollBetween(def.attackSpeedMinMs, def.attackSpeedMaxMs),
      attackSpeedMinMs: def.attackSpeedMinMs,
      attackSpeedMaxMs: def.attackSpeedMaxMs,
      slowMultiplier: 1,
      abilities: def.abilities,
      abilityCooldowns: cooldowns,
      alive: true,
    }
  }

  private rollBetween(min: number, max: number) {
    return min + Math.random() * (max - min)
  }

  private rollEnemyAttackInterval(enemy: EnemyState) {
    const slowed = Math.max(1, enemy.slowMultiplier)
    return this.rollBetween(enemy.attackSpeedMinMs, enemy.attackSpeedMaxMs) * slowed
  }

  public applyTalent(nodeId: string) {
    const node = this.findTalentNode(nodeId)
    if (!node) return
    if (this.state.talentPoints <= 0) return
    if (this.state.unlockedTalents.includes(node.id)) return
    if (!this.meetsTalentRequirements(node)) return

    this.state.unlockedTalents.push(node.id)
    this.state.talentPoints -= 1

    if (node.type === 'ability' && node.abilityId) {
      this.learnAbility(node.abilityId)
    } else if (node.type === 'passive' && node.passiveId) {
      this.learnPassive(node.passiveId)
    }
    this.emit()
  }

  private learnAbility(abilityId: string) {
    const ability = abilitiesById.get(abilityId)
    if (!ability) return
    if (!this.state.knownAbilities.includes(abilityId)) {
      this.state.knownAbilities.push(abilityId)
    }
    this.state.equippedAbilityIds[ability.slot] = abilityId
  }

  private learnPassive(passiveId: string) {
    if (!this.state.unlockedPassives.includes(passiveId)) {
      this.state.unlockedPassives.push(passiveId)
      this.recalculateDerivedStats()
    }
  }

  private meetsTalentRequirements(node: TalentNodeDefinition): boolean {
    const prereqs = node.prerequisiteIds ?? []
    const hasPrereqs = prereqs.every((id) => this.state.unlockedTalents.includes(id))
    if (!hasPrereqs) return false
    const required = talentTreeDefinition.rowUnlockRequirements[node.row as keyof typeof talentTreeDefinition.rowUnlockRequirements] ?? 0
    const pointsBeforeRow = this.pointsInRowsBefore(node.row)
    return pointsBeforeRow >= required
  }

  private pointsInRowsBefore(row: number) {
    return this.state.unlockedTalents.filter((id) => {
      const node = this.findTalentNode(id)
      return node && node.row < row
    }).length
  }

  private findTalentNode(id: string): TalentNodeDefinition | undefined {
    for (const row of talentTreeDefinition.rows) {
      const match = row.find((n) => n.id === id)
      if (match) return match
    }
    return undefined
  }
}

import { abilitiesById, abilityList, enemiesById, enemyList, passivesById, talentTreeDefinition } from './data'
import type {
  AbilityDefinition,
  AbilitySlot,
  EnemyDefinition,
  EnemyState,
  GameState,
  GameStateListener,
  TalentNodeDefinition,
} from './types'
import { Renderer } from '@/rendering/renderer'

const PLAYER_BASE_STATS = {
  maxHp: 100,
  baseDamage: 10,
  baseAttackSpeedMs: 2000,
  rageBonusDamage: 3,
  rageCap: 5,
}

const BLOCK_DURATION_MS = 500
const BLOCK_DAMAGE_REDUCTION = 0.5
const BLOCK_COOLDOWN_MS = 5000
const LEVEL_TARGETS = [1, 2, 3, 3, 3, 3, 3, 3, 3, 3]
const MAX_LEVEL = 10

export class Game {
  private state: GameState
  private listeners = new Set<GameStateListener>()
  private renderer: Renderer | null = null
  private rafId: number | null = null
  private lastFrame = 0
  private accumulator = 0
  private readonly tickMs = 1000 / 60

  constructor() {
    this.state = this.createInitialState()
  }

  public setRenderer(renderer: Renderer | null) {
    this.renderer = renderer
  }

  public subscribe(listener: GameStateListener): () => void {
    this.listeners.add(listener)
    listener(this.snapshot())
    return () => this.listeners.delete(listener)
  }

  public getState(): GameState {
    return this.snapshot()
  }

  private snapshot(): GameState {
    return JSON.parse(JSON.stringify(this.state))
  }

  private emit() {
    const snap = this.snapshot()
    this.listeners.forEach((l) => l(snap))
  }

  private createInitialState(): GameState {
    return {
      phase: 'idle',
      level: 1,
      fightCount: 0,
      fightsToNextLevel: LEVEL_TARGETS[0],
      talentPoints: 0,
      targetIndex: 0,
      unlockedTalents: [],
      unlockedPassives: [],
      knownAbilities: [],
      equippedAbilityIds: { Q: null, W: null, E: null, R: null },
      player: {
        name: 'Rage Warrior',
        hp: PLAYER_BASE_STATS.maxHp,
        maxHp: PLAYER_BASE_STATS.maxHp,
        baseDamage: PLAYER_BASE_STATS.baseDamage,
        baseAttackSpeedMs: PLAYER_BASE_STATS.baseAttackSpeedMs,
        attackTimerMs: PLAYER_BASE_STATS.baseAttackSpeedMs,
        rage: 0,
        rageCap: PLAYER_BASE_STATS.rageCap,
        rageBonusDamage: PLAYER_BASE_STATS.rageBonusDamage,
        abilityCooldowns: { Q: 0, W: 0, E: 0, R: 0 },
        blockCooldownMs: 0,
        buffs: [],
        empoweredAttack: null,
        derived: {
          attackSpeedMultiplier: 1,
          flatDamage: 0,
          maxHp: PLAYER_BASE_STATS.maxHp,
          damageReduction: 0,
        },
      },
      enemies: [],
    }
  }

  public startNewRun() {
    this.state = this.createInitialState()
    this.spawnNextEnemy(true)
    this.emit()
  }

  public startLoop() {
    if (this.rafId) return
    this.lastFrame = performance.now()
    const step = (time: number) => {
      const delta = time - this.lastFrame
      this.lastFrame = time
      this.accumulator += delta
      while (this.accumulator >= this.tickMs) {
        this.update(this.tickMs)
        this.accumulator -= this.tickMs
      }
      this.renderer?.render(this.state)
      this.rafId = requestAnimationFrame(step)
    }
    this.rafId = requestAnimationFrame(step)
  }

  public stopLoop() {
    if (this.rafId) cancelAnimationFrame(this.rafId)
    this.rafId = null
  }

  private update(deltaMs: number) {
    if (this.state.phase !== 'combat') return
    this.tickPlayer(deltaMs)
    this.tickEnemies(deltaMs)
    this.checkCombatResolution()
    this.emit()
  }

  private tickPlayer(deltaMs: number) {
    const player = this.state.player
    this.reduceAbilityCooldowns(player.abilityCooldowns, deltaMs)
    player.blockCooldownMs = Math.max(0, player.blockCooldownMs - deltaMs)
    this.updateBuffs(deltaMs)

    const interval = this.getPlayerAttackInterval()
    player.attackTimerMs = Math.max(0, player.attackTimerMs - deltaMs)
    if (player.attackTimerMs <= 0) {
      this.performPlayerAttack()
      player.attackTimerMs = interval
    }
  }

  private tickEnemies(deltaMs: number) {
    for (const enemy of this.state.enemies) {
      if (!enemy.alive) continue
      this.reduceAbilityCooldowns(enemy.abilityCooldowns, deltaMs)
      enemy.attackTimerMs = Math.max(0, enemy.attackTimerMs - deltaMs)
      if (enemy.attackTimerMs <= 0) {
        this.performEnemyAttack(enemy)
        enemy.attackTimerMs = this.rollEnemyAttackInterval(enemy)
      }
      this.tryEnemyAbilities(enemy)
    }
  }

  private updateBuffs(deltaMs: number) {
    const player = this.state.player
    player.buffs = player.buffs
      .map((buff) => ({ ...buff, remainingMs: buff.remainingMs - deltaMs }))
      .filter((buff) => buff.remainingMs > 0)
    this.recalculateDerivedStats()
  }

  private recalculateDerivedStats() {
    const player = this.state.player
    const passiveMods = this.state.unlockedPassives
      .map((id) => passivesById.get(id)?.statModifiers)
      .filter(Boolean)
      .reduce(
        (acc, mods) => ({
          attackSpeedMultiplier: acc.attackSpeedMultiplier * (mods!.attackSpeedMultiplier ?? 1),
          flatDamage: acc.flatDamage + (mods!.flatDamage ?? 0),
          maxHp: acc.maxHp * (mods!.maxHp ?? 1),
          damageReduction: acc.damageReduction + (mods!.damageReduction ?? 0),
        }),
        { attackSpeedMultiplier: 1, flatDamage: 0, maxHp: 1, damageReduction: 0 },
      )

    const buffAttackSpeed = player.buffs
      .filter((b) => b.type === 'attackSpeed')
      .reduce((acc, b) => acc + (b.attackSpeedBonus ?? 0), 0)
    const buffDamageReduction = player.buffs
      .filter((b) => b.type === 'damageReduction')
      .reduce((acc, b) => Math.max(acc, b.damageReduction ?? 0), 0)

    player.derived = {
      attackSpeedMultiplier: passiveMods.attackSpeedMultiplier + buffAttackSpeed,
      flatDamage: passiveMods.flatDamage,
      maxHp: Math.round(PLAYER_BASE_STATS.maxHp * passiveMods.maxHp),
      damageReduction: Math.min(0.9, passiveMods.damageReduction + buffDamageReduction),
    }
    player.maxHp = player.derived.maxHp
    player.hp = Math.min(player.hp, player.maxHp)
  }

  private reduceAbilityCooldowns(record: Record<string, number>, deltaMs: number) {
    for (const key of Object.keys(record)) {
      record[key] = Math.max(0, record[key] - deltaMs)
    }
  }

  private getPlayerAttackInterval() {
    const player = this.state.player
    const speed = Math.max(0.5, player.derived.attackSpeedMultiplier)
    return PLAYER_BASE_STATS.baseAttackSpeedMs / speed
  }

  private performPlayerAttack() {
    const target = this.getCurrentTarget()
    if (!target) return
    const player = this.state.player
    const rageBonus = player.rage * player.rageBonusDamage
    let damage = player.baseDamage + player.derived.flatDamage + rageBonus

    const empowered = player.empoweredAttack
    if (empowered) {
      target.slowMultiplier = 1 + empowered.slowPercent
      target.attackTimerMs += empowered.slowDurationMs * empowered.slowPercent
      player.empoweredAttack = null
    }

    this.dealDamageToEnemy(target, damage)
  }

  private performEnemyAttack(enemy: EnemyState) {
    const player = this.state.player
    if (this.state.phase !== 'combat') return
    const reduction = 1 - player.derived.damageReduction
    const damage = Math.max(0, enemy.baseDamage * reduction)
    player.hp = Math.max(0, player.hp - damage)
  }

  private tryEnemyAbilities(enemy: EnemyState) {
    for (const ability of enemy.abilities) {
      const cd = enemy.abilityCooldowns[ability.id] ?? 0
      if (cd > 0 || !enemy.alive) continue
      if (ability.effect === 'heal') {
        if (enemy.hp < enemy.maxHp * 0.5) {
          enemy.hp = Math.min(enemy.maxHp, enemy.hp + (ability.values.healAmount ?? 0))
          enemy.abilityCooldowns[ability.id] = ability.cooldownMs
        }
      } else if (ability.effect === 'damageBuff') {
        enemy.baseDamage *= ability.values.damageMultiplier ?? 1.2
        enemy.abilityCooldowns[ability.id] = ability.cooldownMs
      } else if (ability.effect === 'instantAttack') {
        this.performEnemyAttack(enemy)
        enemy.abilityCooldowns[ability.id] = ability.cooldownMs
      }
    }
  }

  private checkCombatResolution() {
    const allDead = this.state.enemies.every((e) => !e.alive)
    if (allDead) {
      this.onVictory()
    } else if (this.state.player.hp <= 0) {
      this.state.phase = 'defeat'
    }
  }

  private onVictory() {
    this.state.phase = 'victory'
    this.state.fightCount += 1
    const needsLevel =
      this.state.level < MAX_LEVEL &&
      this.state.fightCount >= this.state.fightsToNextLevel
    if (needsLevel) {
      this.state.level += 1
      this.state.talentPoints += 1
      const nextTarget = LEVEL_TARGETS[Math.min(this.state.level - 1, LEVEL_TARGETS.length - 1)]
      this.state.fightsToNextLevel = this.state.fightCount + nextTarget
      this.state.phase = 'levelUp'
    }
  }

  public resumeAfterLevel() {
    if (this.state.phase === 'levelUp' || this.state.phase === 'victory') {
      this.spawnNextEnemy(false)
      this.state.phase = 'combat'
      this.emit()
    }
  }

  public selectNextTarget() {
    const alive = this.state.enemies.filter((e) => e.alive)
    if (!alive.length) return
    const current = this.getCurrentTarget()
    const currentIdx = alive.findIndex((e) => e.id === current?.id)
    const next = (currentIdx + 1) % alive.length
    const target = alive[next]
    const fullIdx = this.state.enemies.findIndex((e) => e.id === target.id)
    this.state.targetIndex = fullIdx >= 0 ? fullIdx : 0
    this.emit()
  }

  public selectPrevTarget() {
    const alive = this.state.enemies.filter((e) => e.alive)
    if (!alive.length) return
    const current = this.getCurrentTarget()
    const currentIdx = alive.findIndex((e) => e.id === current?.id)
    const next = (currentIdx - 1 + alive.length) % alive.length
    const target = alive[next]
    const fullIdx = this.state.enemies.findIndex((e) => e.id === target.id)
    this.state.targetIndex = fullIdx >= 0 ? fullIdx : 0
    this.emit()
  }

  public activateBlock() {
    const player = this.state.player
    if (player.blockCooldownMs > 0) return
    player.buffs.push({
      id: 'block',
      remainingMs: BLOCK_DURATION_MS,
      type: 'damageReduction',
      damageReduction: BLOCK_DAMAGE_REDUCTION,
    })
    player.attackTimerMs += BLOCK_DURATION_MS
    player.blockCooldownMs = BLOCK_COOLDOWN_MS
    this.recalculateDerivedStats()
    this.emit()
  }

  public activateAbility(slot: AbilitySlot) {
    const abilityId = this.state.equippedAbilityIds[slot]
    if (!abilityId) return
    const ability = abilitiesById.get(abilityId)
    if (!ability) return
    const remaining = this.state.player.abilityCooldowns[slot]
    if (remaining > 0) return

    switch (ability.effect) {
      case 'generator':
        this.castGenerator(ability)
        break
      case 'attackSpeedBuff':
        this.castAttackSpeedBuff(ability)
        break
      case 'empowerNextAttack':
        this.castEmpower(ability)
        break
      case 'consumeRage':
        this.castConsumer(ability)
        break
    }
    this.state.player.abilityCooldowns[slot] = ability.cooldownMs
    this.emit()
  }

  private castGenerator(ability: AbilityDefinition) {
    this.performPlayerAttack()
    this.state.player.attackTimerMs = this.getPlayerAttackInterval()
    this.state.player.rage = Math.min(
      this.state.player.rageCap,
      this.state.player.rage + (ability.values.rageGain ?? 1),
    )
  }

  private castAttackSpeedBuff(ability: AbilityDefinition) {
    const bonus = ability.values.attackSpeedBonus ?? 0.3
    const duration = ability.values.durationMs ?? 4000
    this.state.player.buffs.push({
      id: ability.id,
      remainingMs: duration,
      type: 'attackSpeed',
      attackSpeedBonus: bonus,
    })
    this.recalculateDerivedStats()
  }

  private castEmpower(ability: AbilityDefinition) {
    this.state.player.empoweredAttack = {
      slowPercent: ability.values.slowPercent ?? 0.25,
      slowDurationMs: ability.values.slowDurationMs ?? 3000,
    }
  }

  private castConsumer(ability: AbilityDefinition) {
    const target = this.getCurrentTarget()
    if (!target) return
    const rage = this.state.player.rage
    const base = ability.values.consumeBaseDamage ?? 5
    const per = ability.values.consumePerRage ?? 8
    const damage = base + per * rage
    this.state.player.rage = 0
    this.performInterrupt()
    this.dealDamageToEnemy(target, damage)
  }

  private performInterrupt() {
    this.state.player.attackTimerMs = this.getPlayerAttackInterval()
  }

  private dealDamageToEnemy(enemy: EnemyState, damage: number) {
    if (!enemy.alive) return
    enemy.hp = Math.max(0, enemy.hp - damage)
    if (enemy.hp <= 0) {
      enemy.alive = false
    }
  }

  private getCurrentTarget() {
    const alive = this.state.enemies.filter((e) => e.alive)
    if (!alive.length) return null
    const desired = this.state.enemies[this.state.targetIndex]
    if (desired?.alive) return desired
    return alive[0]
  }

  private spawnNextEnemy(isTutorial: boolean) {
    const definition = isTutorial
      ? enemiesById.get('tutorialDummy')
      : this.randomEnemy()
    if (!definition) return
    const enemy = this.instantiateEnemy(definition)
    this.state.enemies = [enemy]
    this.state.targetIndex = 0
    this.state.phase = 'combat'
  }

  private randomEnemy(): EnemyDefinition | undefined {
    const pool = enemyList.filter((e) => e.id !== 'tutorialDummy')
    return pool[Math.floor(Math.random() * pool.length)]
  }

  private instantiateEnemy(def: EnemyDefinition) {
    const cooldowns: Record<string, number> = {}
    def.abilities.forEach((a) => (cooldowns[a.id] = 0))
    return {
      id: def.id,
      name: def.name,
      hp: def.maxHp,
      maxHp: def.maxHp,
      baseDamage: def.baseDamage,
      attackTimerMs: this.rollBetween(def.attackSpeedMinMs, def.attackSpeedMaxMs),
      attackSpeedMinMs: def.attackSpeedMinMs,
      attackSpeedMaxMs: def.attackSpeedMaxMs,
      slowMultiplier: 1,
      abilities: def.abilities,
      abilityCooldowns: cooldowns,
      alive: true,
    }
  }

  private rollBetween(min: number, max: number) {
    return min + Math.random() * (max - min)
  }

  private rollEnemyAttackInterval(enemy: EnemyState) {
    const slowed = Math.max(1, enemy.slowMultiplier)
    return this.rollBetween(enemy.attackSpeedMinMs, enemy.attackSpeedMaxMs) * slowed
  }

  public applyTalent(nodeId: string) {
    const node = this.findTalentNode(nodeId)
    if (!node) return
    if (this.state.talentPoints <= 0) return
    if (this.state.unlockedTalents.includes(node.id)) return
    if (!this.meetsTalentRequirements(node)) return

    this.state.unlockedTalents.push(node.id)
    this.state.talentPoints -= 1

    if (node.type === 'ability' && node.abilityId) {
      this.learnAbility(node.abilityId)
    } else if (node.type === 'passive' && node.passiveId) {
      this.learnPassive(node.passiveId)
    }
    this.emit()
  }

  private learnAbility(abilityId: string) {
    const ability = abilitiesById.get(abilityId)
    if (!ability) return
    if (!this.state.knownAbilities.includes(abilityId)) {
      this.state.knownAbilities.push(abilityId)
    }
    this.state.equippedAbilityIds[ability.slot] = abilityId
  }

  private learnPassive(passiveId: string) {
    if (!this.state.unlockedPassives.includes(passiveId)) {
      this.state.unlockedPassives.push(passiveId)
      this.recalculateDerivedStats()
    }
  }

  private meetsTalentRequirements(node: TalentNodeDefinition): boolean {
    const prereqs = node.prerequisiteIds ?? []
    const hasPrereqs = prereqs.every((id) => this.state.unlockedTalents.includes(id))
    if (!hasPrereqs) return false
    const required = talentTreeDefinition.rowUnlockRequirements[node.row] ?? 0
    const pointsBeforeRow = this.pointsInRowsBefore(node.row)
    return pointsBeforeRow >= required
  }

  private pointsInRowsBefore(row: number) {
    return this.state.unlockedTalents.filter((id) => {
      const node = this.findTalentNode(id)
      return node && node.row < row
    }).length
  }

  private findTalentNode(id: string): TalentNodeDefinition | undefined {
    for (const row of talentTreeDefinition.rows) {
      const match = row.find((n) => n.id === id)
      if (match) return match
    }
    return undefined
  }
}

import { abilitiesById, enemiesById, enemyList, passivesById, talentTreeDefinition } from './data'
import type {
  AbilityDefinition,
  AbilitySlot,
  EnemyDefinition,
  EnemyState,
  GameState,
  GameStateListener,
  TalentNodeDefinition,
} from './types'
import { Renderer } from '@/rendering/renderer'

const PLAYER_BASE_STATS = {
  maxHp: 100,
  baseDamage: 10,
  baseAttackSpeedMs: 2000,
  rageBonusDamage: 3,
  rageCap: 5,
}

const BLOCK_DURATION_MS = 500
const BLOCK_DAMAGE_REDUCTION = 0.5
const BLOCK_COOLDOWN_MS = 5000
const LEVEL_TARGETS = [1, 2, 3, 3, 3, 3, 3, 3, 3, 3]
const MAX_LEVEL = 10

export class Game {
  private state: GameState
  private listeners = new Set<GameStateListener>()
  private renderer: Renderer | null = null
  private rafId: number | null = null
  private lastFrame = 0
  private accumulator = 0
  private readonly tickMs = 1000 / 60

  constructor() {
    this.state = this.createInitialState()
  }

  public setRenderer(renderer: Renderer | null) {
    this.renderer = renderer
  }

  public subscribe(listener: GameStateListener): () => void {
    this.listeners.add(listener)
    listener(this.snapshot())
    return () => this.listeners.delete(listener)
  }

  public getState(): GameState {
    return this.snapshot()
  }

  private snapshot(): GameState {
    return JSON.parse(JSON.stringify(this.state))
  }

  private emit() {
    const snap = this.snapshot()
    this.listeners.forEach((l) => l(snap))
  }

  private createInitialState(): GameState {
    return {
      phase: 'idle',
      level: 1,
      fightCount: 0,
      fightsToNextLevel: LEVEL_TARGETS[0],
      talentPoints: 0,
      targetIndex: 0,
      unlockedTalents: [],
      unlockedPassives: [],
      knownAbilities: [],
      equippedAbilityIds: { Q: null, W: null, E: null, R: null },
      player: {
        name: 'Rage Warrior',
        hp: PLAYER_BASE_STATS.maxHp,
        maxHp: PLAYER_BASE_STATS.maxHp,
        baseDamage: PLAYER_BASE_STATS.baseDamage,
        baseAttackSpeedMs: PLAYER_BASE_STATS.baseAttackSpeedMs,
        attackTimerMs: PLAYER_BASE_STATS.baseAttackSpeedMs,
        rage: 0,
        rageCap: PLAYER_BASE_STATS.rageCap,
        rageBonusDamage: PLAYER_BASE_STATS.rageBonusDamage,
        abilityCooldowns: { Q: 0, W: 0, E: 0, R: 0 },
        blockCooldownMs: 0,
        buffs: [],
        empoweredAttack: null,
        derived: {
          attackSpeedMultiplier: 1,
          flatDamage: 0,
          maxHp: PLAYER_BASE_STATS.maxHp,
          damageReduction: 0,
        },
      },
      enemies: [],
    }
  }

  public startNewRun() {
    this.state = this.createInitialState()
    this.spawnNextEnemy(true)
    this.emit()
  }

  public startLoop() {
    if (this.rafId) return
    this.lastFrame = performance.now()
    const step = (time: number) => {
      const delta = time - this.lastFrame
      this.lastFrame = time
      this.accumulator += delta
      while (this.accumulator >= this.tickMs) {
        this.update(this.tickMs)
        this.accumulator -= this.tickMs
      }
      this.renderer?.render(this.state)
      this.rafId = requestAnimationFrame(step)
    }
    this.rafId = requestAnimationFrame(step)
  }

  public stopLoop() {
    if (this.rafId) cancelAnimationFrame(this.rafId)
    this.rafId = null
  }

  private update(deltaMs: number) {
    if (this.state.phase !== 'combat') return
    this.tickPlayer(deltaMs)
    this.tickEnemies(deltaMs)
    this.checkCombatResolution()
    this.emit()
  }

  private tickPlayer(deltaMs: number) {
    const player = this.state.player
    this.reduceAbilityCooldowns(player.abilityCooldowns, deltaMs)
    player.blockCooldownMs = Math.max(0, player.blockCooldownMs - deltaMs)
    this.updateBuffs(deltaMs)

    const interval = this.getPlayerAttackInterval()
    player.attackTimerMs = Math.max(0, player.attackTimerMs - deltaMs)
    if (player.attackTimerMs <= 0) {
      this.performPlayerAttack()
      player.attackTimerMs = interval
    }
  }

  private tickEnemies(deltaMs: number) {
    for (const enemy of this.state.enemies) {
      if (!enemy.alive) continue
      this.reduceAbilityCooldowns(enemy.abilityCooldowns, deltaMs)
      enemy.attackTimerMs = Math.max(0, enemy.attackTimerMs - deltaMs)
      if (enemy.attackTimerMs <= 0) {
        this.performEnemyAttack(enemy)
        enemy.attackTimerMs = this.rollEnemyAttackInterval(enemy)
      }
      this.tryEnemyAbilities(enemy)
    }
  }

  private updateBuffs(deltaMs: number) {
    const player = this.state.player
    player.buffs = player.buffs
      .map((buff) => ({ ...buff, remainingMs: buff.remainingMs - deltaMs }))
      .filter((buff) => buff.remainingMs > 0)
    this.recalculateDerivedStats()
  }

  private recalculateDerivedStats() {
    const player = this.state.player
    const passiveMods = this.state.unlockedPassives
      .map((id) => passivesById.get(id)?.statModifiers)
      .filter(Boolean)
      .reduce(
        (acc, mods) => ({
          attackSpeedMultiplier: acc.attackSpeedMultiplier * (mods!.attackSpeedMultiplier ?? 1),
          flatDamage: acc.flatDamage + (mods!.flatDamage ?? 0),
          maxHp: acc.maxHp * (mods!.maxHp ?? 1),
          damageReduction: acc.damageReduction + (mods!.damageReduction ?? 0),
        }),
        { attackSpeedMultiplier: 1, flatDamage: 0, maxHp: 1, damageReduction: 0 },
      )

    const buffAttackSpeed = player.buffs
      .filter((b) => b.type === 'attackSpeed')
      .reduce((acc, b) => acc + (b.attackSpeedBonus ?? 0), 0)
    const buffDamageReduction = player.buffs
      .filter((b) => b.type === 'damageReduction')
      .reduce((acc, b) => Math.max(acc, b.damageReduction ?? 0), 0)

    player.derived = {
      attackSpeedMultiplier: passiveMods.attackSpeedMultiplier + buffAttackSpeed,
      flatDamage: passiveMods.flatDamage,
      maxHp: Math.round(PLAYER_BASE_STATS.maxHp * passiveMods.maxHp),
      damageReduction: Math.min(0.9, passiveMods.damageReduction + buffDamageReduction),
    }
    player.maxHp = player.derived.maxHp
    player.hp = Math.min(player.hp, player.maxHp)
  }

  private reduceAbilityCooldowns(record: Record<string, number>, deltaMs: number) {
    for (const key of Object.keys(record)) {
      record[key] = Math.max(0, record[key] - deltaMs)
    }
  }

  private getPlayerAttackInterval() {
    const player = this.state.player
    const speed = Math.max(0.5, player.derived.attackSpeedMultiplier)
    return PLAYER_BASE_STATS.baseAttackSpeedMs / speed
  }

  private performPlayerAttack() {
    const target = this.getCurrentTarget()
    if (!target) return
    const player = this.state.player
    const rageBonus = player.rage * player.rageBonusDamage
    let damage = player.baseDamage + player.derived.flatDamage + rageBonus

    const empowered = player.empoweredAttack
    if (empowered) {
      target.slowMultiplier = 1 + empowered.slowPercent
      target.attackTimerMs += empowered.slowDurationMs * empowered.slowPercent
      player.empoweredAttack = null
    }

    this.dealDamageToEnemy(target, damage)
  }

  private performEnemyAttack(enemy: EnemyState) {
    const player = this.state.player
    if (this.state.phase !== 'combat') return
    const reduction = 1 - player.derived.damageReduction
    const damage = Math.max(0, enemy.baseDamage * reduction)
    player.hp = Math.max(0, player.hp - damage)
  }

  private tryEnemyAbilities(enemy: EnemyState) {
    for (const ability of enemy.abilities) {
      const cd = enemy.abilityCooldowns[ability.id] ?? 0
      if (cd > 0 || !enemy.alive) continue
      if (ability.effect === 'heal') {
        if (enemy.hp < enemy.maxHp * 0.5) {
          enemy.hp = Math.min(enemy.maxHp, enemy.hp + (ability.values.healAmount ?? 0))
          enemy.abilityCooldowns[ability.id] = ability.cooldownMs
        }
      } else if (ability.effect === 'damageBuff') {
        enemy.baseDamage *= ability.values.damageMultiplier ?? 1.2
        enemy.abilityCooldowns[ability.id] = ability.cooldownMs
      } else if (ability.effect === 'instantAttack') {
        this.performEnemyAttack(enemy)
        enemy.abilityCooldowns[ability.id] = ability.cooldownMs
      }
    }
  }

  private checkCombatResolution() {
    const allDead = this.state.enemies.every((e) => !e.alive)
    if (allDead) {
      this.onVictory()
    } else if (this.state.player.hp <= 0) {
      this.state.phase = 'defeat'
    }
  }

  private onVictory() {
    this.state.phase = 'victory'
    this.state.fightCount += 1
    const needsLevel =
      this.state.level < MAX_LEVEL &&
      this.state.fightCount >= this.state.fightsToNextLevel
    if (needsLevel) {
      this.state.level += 1
      this.state.talentPoints += 1
      const nextTarget = LEVEL_TARGETS[Math.min(this.state.level - 1, LEVEL_TARGETS.length - 1)]
      this.state.fightsToNextLevel = this.state.fightCount + nextTarget
      this.state.phase = 'levelUp'
    }
  }

  public resumeAfterLevel() {
    if (this.state.phase === 'levelUp' || this.state.phase === 'victory') {
      this.spawnNextEnemy(false)
      this.state.phase = 'combat'
      this.emit()
    }
  }

  public selectNextTarget() {
    const alive = this.state.enemies.filter((e) => e.alive)
    if (!alive.length) return
    const current = this.getCurrentTarget()
    const currentIdx = alive.findIndex((e) => e.id === current?.id)
    const next = (currentIdx + 1) % alive.length
    const target = alive[next]
    const fullIdx = this.state.enemies.findIndex((e) => e.id === target.id)
    this.state.targetIndex = fullIdx >= 0 ? fullIdx : 0
    this.emit()
  }

  public selectPrevTarget() {
    const alive = this.state.enemies.filter((e) => e.alive)
    if (!alive.length) return
    const current = this.getCurrentTarget()
    const currentIdx = alive.findIndex((e) => e.id === current?.id)
    const next = (currentIdx - 1 + alive.length) % alive.length
    const target = alive[next]
    const fullIdx = this.state.enemies.findIndex((e) => e.id === target.id)
    this.state.targetIndex = fullIdx >= 0 ? fullIdx : 0
    this.emit()
  }

  public activateBlock() {
    const player = this.state.player
    if (player.blockCooldownMs > 0) return
    player.buffs.push({
      id: 'block',
      remainingMs: BLOCK_DURATION_MS,
      type: 'damageReduction',
      damageReduction: BLOCK_DAMAGE_REDUCTION,
    })
    player.attackTimerMs += BLOCK_DURATION_MS
    player.blockCooldownMs = BLOCK_COOLDOWN_MS
    this.recalculateDerivedStats()
    this.emit()
  }

  public activateAbility(slot: AbilitySlot) {
    const abilityId = this.state.equippedAbilityIds[slot]
    if (!abilityId) return
    const ability = abilitiesById.get(abilityId)
    if (!ability) return
    const remaining = this.state.player.abilityCooldowns[slot]
    if (remaining > 0) return

    switch (ability.effect) {
      case 'generator':
        this.castGenerator(ability)
        break
      case 'attackSpeedBuff':
        this.castAttackSpeedBuff(ability)
        break
      case 'empowerNextAttack':
        this.castEmpower(ability)
        break
      case 'consumeRage':
        this.castConsumer(ability)
        break
    }
    this.state.player.abilityCooldowns[slot] = ability.cooldownMs
    this.emit()
  }

  private castGenerator(ability: AbilityDefinition) {
    this.performPlayerAttack()
    this.state.player.attackTimerMs = this.getPlayerAttackInterval()
    this.state.player.rage = Math.min(
      this.state.player.rageCap,
      this.state.player.rage + (ability.values.rageGain ?? 1),
    )
  }

  private castAttackSpeedBuff(ability: AbilityDefinition) {
    const bonus = ability.values.attackSpeedBonus ?? 0.3
    const duration = ability.values.durationMs ?? 4000
    this.state.player.buffs.push({
      id: ability.id,
      remainingMs: duration,
      type: 'attackSpeed',
      attackSpeedBonus: bonus,
    })
    this.recalculateDerivedStats()
  }

  private castEmpower(ability: AbilityDefinition) {
    this.state.player.empoweredAttack = {
      slowPercent: ability.values.slowPercent ?? 0.25,
      slowDurationMs: ability.values.slowDurationMs ?? 3000,
    }
  }

  private castConsumer(ability: AbilityDefinition) {
    const target = this.getCurrentTarget()
    if (!target) return
    const rage = this.state.player.rage
    const base = ability.values.consumeBaseDamage ?? 5
    const per = ability.values.consumePerRage ?? 8
    const damage = base + per * rage
    this.state.player.rage = 0
    this.performInterrupt()
    this.dealDamageToEnemy(target, damage)
  }

  private performInterrupt() {
    this.state.player.attackTimerMs = this.getPlayerAttackInterval()
  }

  private dealDamageToEnemy(enemy: EnemyState, damage: number) {
    if (!enemy.alive) return
    enemy.hp = Math.max(0, enemy.hp - damage)
    if (enemy.hp <= 0) {
      enemy.alive = false
    }
  }

  private getCurrentTarget() {
    const alive = this.state.enemies.filter((e) => e.alive)
    if (!alive.length) return null
    const desired = this.state.enemies[this.state.targetIndex]
    if (desired?.alive) return desired
    return alive[0]
  }

  private spawnNextEnemy(isTutorial: boolean) {
    const definition = isTutorial
      ? enemiesById.get('tutorialDummy')
      : this.randomEnemy()
    if (!definition) return
    const enemy = this.instantiateEnemy(definition)
    this.state.enemies = [enemy]
    this.state.targetIndex = 0
    this.state.phase = 'combat'
  }

  private randomEnemy(): EnemyDefinition | undefined {
    const pool = enemyList.filter((e) => e.id !== 'tutorialDummy')
    return pool[Math.floor(Math.random() * pool.length)]
  }

  private instantiateEnemy(def: EnemyDefinition) {
    const cooldowns: Record<string, number> = {}
    def.abilities.forEach((a) => (cooldowns[a.id] = 0))
    return {
      id: def.id,
      name: def.name,
      hp: def.maxHp,
      maxHp: def.maxHp,
      baseDamage: def.baseDamage,
      attackTimerMs: this.rollBetween(def.attackSpeedMinMs, def.attackSpeedMaxMs),
      attackSpeedMinMs: def.attackSpeedMinMs,
      attackSpeedMaxMs: def.attackSpeedMaxMs,
      slowMultiplier: 1,
      abilities: def.abilities,
      abilityCooldowns: cooldowns,
      alive: true,
    }
  }

  private rollBetween(min: number, max: number) {
    return min + Math.random() * (max - min)
  }

  private rollEnemyAttackInterval(enemy: EnemyState) {
    const slowed = Math.max(1, enemy.slowMultiplier)
    return this.rollBetween(enemy.attackSpeedMinMs, enemy.attackSpeedMaxMs) * slowed
  }

  public applyTalent(nodeId: string) {
    const node = this.findTalentNode(nodeId)
    if (!node) return
    if (this.state.talentPoints <= 0) return
    if (this.state.unlockedTalents.includes(node.id)) return
    if (!this.meetsTalentRequirements(node)) return

    this.state.unlockedTalents.push(node.id)
    this.state.talentPoints -= 1

    if (node.type === 'ability' && node.abilityId) {
      this.learnAbility(node.abilityId)
    } else if (node.type === 'passive' && node.passiveId) {
      this.learnPassive(node.passiveId)
    }
    this.emit()
  }

  private learnAbility(abilityId: string) {
    const ability = abilitiesById.get(abilityId)
    if (!ability) return
    if (!this.state.knownAbilities.includes(abilityId)) {
      this.state.knownAbilities.push(abilityId)
    }
    this.state.equippedAbilityIds[ability.slot] = abilityId
  }

  private learnPassive(passiveId: string) {
    if (!this.state.unlockedPassives.includes(passiveId)) {
      this.state.unlockedPassives.push(passiveId)
      this.recalculateDerivedStats()
    }
  }

  private meetsTalentRequirements(node: TalentNodeDefinition): boolean {
    const prereqs = node.prerequisiteIds ?? []
    const hasPrereqs = prereqs.every((id) => this.state.unlockedTalents.includes(id))
    if (!hasPrereqs) return false
    const required = talentTreeDefinition.rowUnlockRequirements[node.row] ?? 0
    const pointsBeforeRow = this.pointsInRowsBefore(node.row)
    return pointsBeforeRow >= required
  }

  private pointsInRowsBefore(row: number) {
    return this.state.unlockedTalents.filter((id) => {
      const node = this.findTalentNode(id)
      return node && node.row < row
    }).length
  }

  private findTalentNode(id: string): TalentNodeDefinition | undefined {
    for (const row of talentTreeDefinition.rows) {
      const match = row.find((n) => n.id === id)
      if (match) return match
    }
    return undefined
  }
}

import { useEffect, useState } from 'react'
import type { Game } from '@/game/game'
import type { GameState } from '@/game/types'

export function useGameState(game: Game) {
  const [state, setState] = useState<GameState>(() => game.getState())

  useEffect(() => {
    const unsubscribe = game.subscribe(setState)
    return () => unsubscribe()
  }, [game])

  return state
}

