import { useEffect, useRef } from 'react'
import type { Game } from '@/game/game'
import type { GameState } from '@/game/types'
import { Renderer } from '@/rendering/renderer'

interface CombatScreenProps {
  game: Game
  state: GameState
  onLevelUp: () => void
}

export function CombatScreen({ game, state, onLevelUp }: CombatScreenProps) {
  const canvasRef = useRef<HTMLCanvasElement | null>(null)

  useEffect(() => {
    const canvas = canvasRef.current
    if (!canvas) return
    const renderer = new Renderer(canvas)
    game.setRenderer(renderer)
    game.startLoop()
    return () => game.stopLoop()
  }, [game])

  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if (state.phase !== 'combat') return
      if (e.code === 'Space') {
        e.preventDefault()
        game.activateBlock()
      } else if (e.key === 'ArrowRight') {
        game.selectNextTarget()
      } else if (e.key === 'ArrowLeft') {
        game.selectPrevTarget()
      } else if (['q', 'w', 'e', 'r'].includes(e.key.toLowerCase())) {
        const slot = e.key.toUpperCase() as 'Q' | 'W' | 'E' | 'R'
        game.activateAbility(slot)
      }
    }
    window.addEventListener('keydown', handler)
    return () => window.removeEventListener('keydown', handler)
  }, [game, state.phase])

  useEffect(() => {
    if (state.phase === 'levelUp') onLevelUp()
  }, [state.phase, onLevelUp])

  return (
    <div className="combat-layout">
      <div className="hud">
        <div className="stat-block">
          <div className="label">HP</div>
          <div>
            {Math.round(state.player.hp)} / {state.player.maxHp}
          </div>
        </div>
        <div className="stat-block">
          <div className="label">Rage</div>
          <div>{state.player.rage} / {state.player.rageCap}</div>
        </div>
        <div className="stat-block">
          <div className="label">Level</div>
          <div>{state.level}</div>
        </div>
        <div className="stat-block">
          <div className="label">Fight</div>
          <div>{state.fightCount + 1}</div>
        </div>
      </div>

      <canvas ref={canvasRef} width={900} height={520} className="canvas" />

      <div className="ability-bar">
        <AbilitySlot label="Q" cooldown={state.player.abilityCooldowns.Q} total={4000} description="Rage Strike" />
        <AbilitySlot label="W" cooldown={state.player.abilityCooldowns.W} total={10000} description="Battle Fury" />
        <AbilitySlot label="E" cooldown={state.player.abilityCooldowns.E} total={8000} description="Crippling Blow" />
        <AbilitySlot label="R" cooldown={state.player.abilityCooldowns.R} total={12000} description="Rage Unleash" />
        <AbilitySlot label="Space" cooldown={state.player.blockCooldownMs} total={5000} description="Block" />
      </div>
      <p className="muted">Controls: Arrow keys to swap targets, Space to Block, Q/W/E/R for abilities.</p>
    </div>
  )
}

interface SlotProps {
  label: string
  cooldown: number
  total: number
  description: string
}

function AbilitySlot({ label, cooldown, total, description }: SlotProps) {
  const pct = total > 0 ? 1 - cooldown / total : 1
  return (
    <div className="ability-slot">
      <div className="ability-label">{label}</div>
      <div className="ability-progress">
        <div className="ability-fill" style={{ width: `${Math.max(0, Math.min(1, pct)) * 100}%` }} />
      </div>
      <div className="ability-desc">{description}</div>
    </div>
  )
}

import type { TalentNodeDefinition, TalentTreeDefinition } from '@/game/types'

interface TalentTreeProps {
  tree: TalentTreeDefinition
  unlocked: string[]
  talentPoints: number
  onSelect: (nodeId: string) => void
}

export function TalentTree({ tree, unlocked, talentPoints, onSelect }: TalentTreeProps) {
  return (
    <div className="talent-tree">
      {tree.rows.map((row, idx) => (
        <div key={idx} className="talent-row">
          {row.map((node) => {
            const state = getNodeState(node, unlocked, talentPoints, tree)
            return (
              <button
                key={node.id}
                className={`talent-node ${state}`}
                onClick={() => state === 'available' && onSelect(node.id)}
                disabled={state !== 'available'}
              >
                <div className="talent-label">{node.label}</div>
                <div className="talent-type">{node.type === 'ability' ? 'Ability' : 'Passive'}</div>
              </button>
            )
          })}
        </div>
      ))}
      <p className="muted">Spend talent points to unlock abilities and passives. Row unlocks require points in prior rows.</p>
    </div>
  )
}

function getNodeState(
  node: TalentNodeDefinition,
  unlocked: string[],
  talentPoints: number,
  tree: TalentTreeDefinition,
): 'purchased' | 'available' | 'locked' {
  if (unlocked.includes(node.id)) return 'purchased'
  if (talentPoints <= 0) return 'locked'
  const prereqs = node.prerequisiteIds ?? []
  const hasPrereqs = prereqs.every((p) => unlocked.includes(p))
  if (!hasPrereqs) return 'locked'
  const required = tree.rowUnlockRequirements[node.row] ?? 0
  const pointsInPreviousRows = unlocked.filter((id) => {
    const match = findNode(tree, id)
    return match && match.row < node.row
  }).length
  if (pointsInPreviousRows < required) return 'locked'
  return 'available'
}

function findNode(tree: TalentTreeDefinition, id: string) {
  for (const row of tree.rows) {
    const node = row.find((n) => n.id === id)
    if (node) return node
  }
  return undefined
}

